where.if:
AND INVESTOR_ENTERPRISE_ID IN (
    SELECT ORGID FROM TBL_ORGANIZATION
    START WITH ORGID = #{companyId}
    CONNECT BY PRIOR ORGID = FATHERORGID
)

mapper.select:
SELECT * FROM INVESTMENT_PROJECT
WHERE INVESTOR_ENTERPRISE_ID = #{investorEnterpriseId}
ORDER BY INVESTMENT_START_DATE DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE INVESTEE_ENTERPRISE_ID = #{investeeEnterpriseId}
ORDER BY INVESTMENT_START_DATE DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE INVESTMENT_TYPE = #{investmentType}
ORDER BY PLANNED_INVESTMENT_AMOUNT DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE INVESTMENT_INDUSTRY = #{investmentIndustry}
ORDER BY PLANNED_INVESTMENT_AMOUNT DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE INVESTMENT_REGION = #{investmentRegion}
ORDER BY PLANNED_INVESTMENT_AMOUNT DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE PROJECT_STATUS = #{projectStatus}
ORDER BY UPDATE_TIME DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE INVESTMENT_STAGE = #{investmentStage}
ORDER BY PLANNED_INVESTMENT_AMOUNT DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE RISK_LEVEL = #{riskLevel}
ORDER BY PLANNED_INVESTMENT_AMOUNT DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE APPROVAL_STATUS = #{approvalStatus}
ORDER BY UPDATE_TIME DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE IS_STRATEGIC_INVESTMENT = #{isStrategicInvestment}
ORDER BY PLANNED_INVESTMENT_AMOUNT DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE IS_RELATED_TRANSACTION = #{isRelatedTransaction}
ORDER BY PLANNED_INVESTMENT_AMOUNT DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE NEED_REGULATORY_ATTENTION = #{needRegulatoryAttention}
ORDER BY RISK_LEVEL DESC, PLANNED_INVESTMENT_AMOUNT DESC

SELECT * FROM INVESTMENT_PROJECT
WHERE PROJECT_MANAGER = #{projectManager}
ORDER BY INVESTMENT_START_DATE DESC

mapper.delete:
DELETE FROM INVESTMENT_PROJECT WHERE PROJECT_STATUS = 'CANCELLED' AND UPDATE_TIME <
DATE_SUB(NOW(), INTERVAL #{days} DAY)
SYSDATE - #{days}
